Title: how do I concatenate and join an array of strings with a delimiter in powershell?.
Body: <p>PS C:\Users\User\ps-modules&gt; more .\MyStrings.Tests.ps1</p>
<pre><code>function slist { &quot;1&quot;, &quot;2&quot;, &quot;3&quot; }

Describe 'StringTests' {

  It 'literal -join' {
    &quot;1&quot;, &quot;2&quot;, &quot;3&quot; -join &quot;,&quot; | Should -Be &quot;1,2,3&quot;
  }

  It 'literal -join' {
    @(&quot;1&quot;, &quot;2&quot;, &quot;3&quot;) -join &quot;,&quot; | Should -Be &quot;1,2,3&quot;
  }

  It 'slist returns a list of string' {
    slist | Should -Be @(&quot;1&quot;, &quot;2&quot;, &quot;3&quot;)
  }

  It 'slist -join' {
    slist -join &quot;,&quot; | Should -Be &quot;1,2,3&quot;
