import pandas as pd

df = pd.DataFrame({
    'Index': [0, 1, 2, 3],
    'Schema': ['schema_1', 'schema_2', 'schema_3', 'schema_4'],
    'Column': ['col_1', 'col_2', 'col_3', 'col_4'],
    'Trh1': [pd.NA, 0.02, 0.03, pd.NA],
    'Trh2': [0.01, 0.03, 0.04, pd.NA],
    'Trh3': [pd.NA, pd.NA, 0.05, 0.06],
    'Trh4': [pd.NA, pd.NA, pd.NA, 0.07]
})

def split_row(df):
    new_df = []
    for index, row in df.iterrows():
        if not pd.isnull(row['Trh1']).any() and not pd.isnull(row['Trh2']).any():
            new_df.append([row['Index'], row['Schema'], row['Column'], row['Trh1'], row['Trh2'], pd.NA, pd.NA])
            new_df.append([row['Index'], row['Schema'], row['Column'], pd.NA, pd.NA, row['Trh3'], row['Trh4']])
        else:
            new_df.append([row['Index'], row['Schema'], row['Column'], row['Trh1'], row['Trh2'], row['Trh3'], row['Trh4']])
    return pd.DataFrame(new_df, columns=df.columns)

print(split_row(df))assistant

This code defines a function `split_row` that iterates over each row in the dataframe. If a row contains at least one not NaN value in 'Trh1' and 'Trh2', it splits the row into two separate rows, one with 'Trh1' and 'Trh2' and the other with 'Trh3' and 'Trh4'. Otherwise, it keeps the original row. The function then returns a new dataframe with the split rows.

