def find_second_max(lst):
    if len(lst) < 2:
        return None
    max_value = second_max = float('-inf')
    for num in lst:
        if num > max_value:
            second_max = max_value
            max_value = num
        elif num > second_max and num != max_value:
            second_max = num
    if second_max == float('-inf'):
        return None
    return second_max

