Answers:
```python
def apply_quantifier(k, f, domain):
    if k == 'all':
        return [f(x) for x in domain]
    elif k == 'ex':
        return [f(x) for x in domain if f(x)]
    else:
        raise ValueError("Invalid quantifier")

def loop_over_function(k, f, domain, func):
    if k == 'all':
        return [func(v) for v in apply_quantifier(k, f, domain)]
    elif k == 'ex':
        return [func(v) for v in domain if apply_quantifier(k, f, [v])[0]]

# Example usage:
domain = [1, 2, 3, 4, 5]
f = lambda x: x % 2 == 0
k = 'all'

result = loop_over_function(k, f, domain, lambda x: x)
print(result)  # [0, 2, 4]
```

