import requests
import json

def search_jobs(graphql_url, query, variables):
    headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    }
    data = {
        'query': query,
        'variables': variables
    }
    response = requests.post(graphql_url, headers=headers, json=data)
    return response.json()

def get_job_profile(graphql_url, job_key, variables):
    headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    }
    data = {
        'query': f'''
            query GetJobProfile($jobKey: String!) {{
                freelancerProfileRecords(
                    jobKey: $jobKey
                ) {{
                    title
                    description
                    skills
                    ... on FreelancerProfileRecord {
                        profile
                    }
                }}
            }}
        ''',
        'variables': {'jobKey': job_key}
    }
    response = requests.post(graphql_url, headers=headers, json=data)
    return response.json()

# Example usage
graphql_url = 'https://api.upwork.com/graphql'
query = '''
    query SearchJobs($title: String, $skills: [String], $q: String) {{
        freelancerProfileRecords(
            title: $title
            skills: $skills
            q: $q
        ) {{
            title
            description
            skills
            ... on FreelancerProfileRecord {
                profile
            }
        }}
    }}
'''

variables = {
    'title': 'example title',
    'skills': ['example skill'],
    'q': 'example query'
}

job_key = 'example_job_key'
job_profile = get_job_profile(graphql_url, job_key, variables)
jobs = search_jobs(graphql_url, query, variables)
