    def __init__(self):
        self.parser = reqparse.RequestParser()
        self.parser.add_argument('request_params', type=dict)

    def post(self):
        args = self.parser.parse_args()
        request_params = args['request_params']
        # Your API logic here
        response = requests.post(
            'https://your-api-endpoint.com/registration',
            json=request_params
        )
        if response.status_code == 200:
            return {'message': 'Account created successfully'}
        else:
            return {'message': 'Error creating account'}

if __name__ == '__main__':
    app.run(debug=True)
```

```python
import re
from functools import wraps

def kebab_case_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        route = func.__name__.lower().replace(' ', '-')
        return func(*args, **kwargs)
    return wrapper

class RouteConfig:
    @staticmethod
    def configure_routes(app):
        for name, handler in vars(app).items():
            if hasattr(handler, '__call__'):
                handler = kebab_case_decorator(handler)
                setattr(app, name, handler)

# Usage
from fastapi import FastAPI

app = FastAPI()

class PackageGroupsController:
    @RouteConfig.configure_routes(app)
    def get(self):
        pass

class AnotherController:
    @RouteConfig.configure_routes(app)
    def get(self):
        pass
```

This code defines a decorator `kebab_case_decorator` that converts the name of a controller to kebab-case format. It then defines a class `RouteConfig` with a static method `configure_routes` that applies this decorator to all controller methods in the application.

To use this code, create an instance of the `FastAPI` class and apply the `configure_routes` method to it. Then, define your controllers as usual, and the `configure_routes` method will automatically apply the `kebab_case_decorator` to their methods.

