Answers:
import asyncio
import aiohttp
import time

async def call_service_b(session, url):
    async with session.get(url) as response:
        return await response.text()

async def make_request(session, url):
    try:
        return await call_service_b(session, url)
    except aiohttp.ClientError:
        return None

async def main():
    urls = ['http://service-b-url-1.com', 'http://service-b-url-2.com', 'http://service-b-url-3.com']
    async with aiohttp.ClientSession() as session:
        tasks = []
        for url in urls:
            task = asyncio.create_task(make_request(session, url))
            tasks.append(task)
        results = await asyncio.gather(*tasks)
        for result in results:
            if result:
                print(result)

asyncio.run(main())

