# Create a temporary page to show while waiting for the response
sub show_temporary_page {
    my $self = shift;
    my $response = $self->response;
    $response->header('Content-Type' => 'text/html');
    $response->body('<html><body><h1>Loading...</h1></body></html>');
    return $response;
}

# Check if the async call is ready via Ajax
sub check_async_ready {
    my $self = shift;
    my $response = $self->response;
    $response->header('Content-Type' => 'text/html');
    $response->body('<html><body><h1>Loading...</h1><script>var ready = function(){');
    $response->body('  console.log("Async call is ready");');
    $response->body('  $.ajax({ async: true, url: "/async", success: function() {');
    $response->body('    window.location.href = "/";');
    $response->body('  }});');
    $response->body('};</script></body></html>');
    return $response;
}

# Example async call using Minion
sub async_example {
    my $self = shift;
    my $minion = $self->minion;
    $minion->async(sub {
        my $result = 10;
        $minion->post('/async', { result => $result });
    });
}

# Main application
sub example {
    my $self = shift;
    my $response = $self->response;
    $response->header('Content-Type' => 'text/html');
    $response->body('<html><body><h1>Hello World!</h1></body></html>');
    return $response;
}

# Route to show temporary page
get '/temp' => sub {
    my $self = shift;
    $self->show_temporary_page;
};

# Route to check async call
post '/async' => sub {
    my $self = shift;
    $self->check_async_ready;
};

# Route to run async example
post '/async_example' => sub {
    my $self = shift;
    $self->async_example;
};

# Run the application
my $app = Mojolicious::App->new->start;
