```python
import os
from django.conf import settings

def move_file_safe(file_path):
    temp_dir = settings.MEDIA_ROOT
    destination_dir = os.path.join(temp_dir, os.path.dirname(file_path))
    if not os.path.exists(destination_dir):
        os.makedirs(destination_dir)

    # Check if file exists before attempting to move
    if os.path.exists(file_path):
        # Use os.rename to move the file
        try:
            os.rename(file_path, os.path.join(destination_dir, os.path.basename(file_path)))
        except Exception as e:
            # Handle any exceptions that occur during the move
            print(f"Error moving file: {e}")
    else:
        # If file does not exist, log a message and continue
        print(f"File not found: {file_path}")

# Modify the model's save method to call move_file_safe
class YourModel(models.Model):
    # ...
    def save(self, *args, **kwargs):
        super().save(*args, **kwargs)
        move_file_safe(os.path.join(self.file_path, self.file_name))
```

