  }
  if (!-e $request_filename){
    rewrite ^(.*)$ /index.php break;
  }
  if (!-e $request_filename){
    rewrite ^/(css|assets|landing|storage|installer|js|custom)/(.*)$ /public/$1/$2 break;
  }
}
</code></pre>

Answers:
```python
server {
  listen 80;
  listen [::]:80;
  listen 443 ssl http2;
  listen [::]:443 ssl http2;
  root /path/to/your/root;
  ssl_certificate /path/to/your/ssl/certificate;
  ssl_certificate_key /path/to/your/ssl/certificate/key;
  server_name crm.mydomain.it;

  location ~ \.php$ {
    include fastcgi_params;
    fastcgi_intercept_errors on;
    fastcgi_index index.php;
    fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
    try_files $uri =404;
    fastcgi_read_timeout 3600;
    fastcgi_send_timeout 3600;
    fastcgi_param HTTPS &quot;on&quot;;
    fastcgi_param SERVER_PORT 443;
    fastcgi_pass 127.0.0.1:{{php_fpm_port}};
    fastcgi_param PHP_VALUE &quot;{{php_settings}}&quot;;
  }

  location ~* (\.css|\.js|\.png|\.jpg|\.jpeg|\.gif|robots\.txt|\.ico|\.woff|\.woff2|.ttf|\.svg)$ {
    add_header Access-Control-Allow-Origin &quot;*&quot;;
    expires max;
    access_log off;
  }

  location /public/ {
    autoindex off;
  }

  location / {
    if (!-e $request_filename){
      rewrite ^(.*)$ /%1 redirect;
    }
    if (!-e $request_filename){
      rewrite ^(.*)$ /index.php break;
    }
    if (!-e $request_filename){
      rewrite ^/(css|assets|landing|storage|installer|js|custom)/(.*)$ /public/$1/$2 break;
    }
  }
}
```

```python
import csv
import math

def split_csv_by_groups(file_path, num_files):
    with open(file_path, 'r') as file:
        reader = csv.reader(file)
        data = list(reader)

    id_counts = {}
    for row in data:
        id = row[1]
        if id not in id_counts:
            id_counts[id] = 1
        else:
            id_counts[id] += 1

    groups = {}
    for id, count in id_counts.items():
        group_id = (count - 1) // num_files + 1
        if group_id not in groups:
            groups[group_id] = []
        groups[group_id].append(id)

    for i, group in enumerate(groups.values()):
        file_name = str(i % num_files + 1).zfill(num_files)
        with open(f"{file_name}.csv", 'w', newline='') as output_file:
            writer = csv.writer(output_file)
            for id in group:
                writer.writerow([data[0][0], id])

split_csv_by_groups('input.csv', 3)
```

