```javascript
import { Test, TestingModule } from '@nestjs/testing';
import { AppModule } from './app.module';

describe('AppController', () => {
  let app: TestingModule;

  beforeEach(async () => {
    app = await Test.createTestingModule({
      imports: [AppModule],
    }).compile();
  });

  it('should be defined', () => {
    expect(app.get(AppController)).toBeDefined();
  });
});
```

Explanation:
This is a basic unit test for a NestJS application. It imports the necessary modules from `@nestjs/testing` and creates a test module with the `AppModule`. The `beforeEach` hook is used to compile the test module before each test. The test itself checks if the `AppController` is defined in the test module.

