import unittest

class A:
    def __init__(self, value):
        self.value = value

class A_bundle:
    def __init__(self):
        self.objects = []

    def add_object(self, obj):
        self.objects.append(obj)

def create_test_A():
    return A(1)

class TestA(unittest.TestCase):
    def test(self):
        new_A = create_test_A()
        self.assertEqual(new_A.value, 1)

class TestA_bundle(unittest.TestCase):
    def test_add_object(self):
        new_A1 = create_test_A()
        new_A2 = create_test_A()
        bundle = A_bundle()
        bundle.add_object(new_A1)
        bundle.add_object(new_A2)
        self.assertEqual(len(bundle.objects), 2)
        self.assertIn(new_A1, bundle.objects)
        self.assertIn(new_A2, bundle.objects)

    def test_add_object_twice(self):
        new_A1 = create_test_A()
        new_A2 = create_test_A()
        bundle = A_bundle()
        bundle.add_object(new_A1)
        bundle.add_object(new_A2)
        bundle.add_object(new_A1)  # This should not affect the first object
        self.assertEqual(len(bundle.objects), 2)
        self.assertIn(new_A1, bundle.objects)
        self.assertIn(new_A2, bundle.objects)

if __name__ == '__main__':
    unittest.main()
```

