import re

def match_log_values(expected_log, actual_log):
    expected_pattern = re.compile(rf"Encountered {expected_log['exceptionType']}. Unable to verify user with id {expected_log['userId']}")
    actual_pattern = re.compile(rf"Encountered {actual_log['exceptionType']}. Unable to verify user with id {actual_log['userId']}")

    return expected_pattern.match(actual_log['message']) is not None and actual_pattern.match(actual_log['message']) is not None

# Example usage:
expected_log = {
    'exceptionType': 'NullReferenceException',
    'userId': 1
}

actual_log = {
    'message': "Encountered NullReferenceException. Unable to verify user with id 1"
}

assert match_log_values(expected_log, actual_log)
