Title: Unable to test vue component with v-dialog.
Body: <p>I have been killing myself trying to figure out how to test a Vue component with a v-dialog, something which worked perfectly fine in Vue2. Currently I am using Vue3, Vitest, Vuetify3.</p>
<p>here is a very simple <strong>component</strong> which demonstrates a problem</p>
<pre><code>&lt;template&gt;
  &lt;div&gt;
    &lt;v-btn @click.stop=&quot;dialog=true&quot; class=&quot;open-dialog-btn&quot;&gt;click me please&lt;/v-btn&gt;
    &lt;v-dialog v-model=&quot;dialog&quot; max-width=&quot;290&quot; &gt;
      &lt;div class=&quot;dialog-content&quot;&gt;
        &lt;v-card&gt;welcome to dialog&lt;/v-card&gt;
      &lt;/div&gt;
    &lt;/v-dialog&gt;
  &lt;/div&gt;
&lt;/template&gt;

&lt;script setup&gt;
import {ref} from &quot;vue&quot;;

const dialog = ref(false);
&lt;/script&gt;
</code></pre>
<p>and here is a <strong>unit test</strong> for it:</p>
<pre><code>import '../setup';
import { mount } from '@vue/test-utils';
import { createVuetify } from &quot;vuetify&quot;;
import HelloDialog from &quot;@/components/HelloDialog.vue&quot;;

describe('HelloDialog', () =&gt; {
  let wrapper;
  let vuetify;

  beforeEach(() =&gt; {
    vuetify = createVuetify();
  });

  describe('dialog tests', () =&gt; {
    beforeEach(() =&gt; {
      wrapper = mount(HelloDialog, {
        global: {
          plugins: [vuetify],
        },
      });
    });

    test('test dialog', async () =&gt; {
      expect(wrapper.find('.dialog-content').exists()).toBeFalsy();
      await wrapper.find('.open-dialog-btn').trigger('click');
      console.log(wrapper.html());
      expect(wrapper.find('.dialog-content').exists()).toBeTruthy();
    });
  });
});
</code></pre>
<p>the last line in unit test is not working - dialog content is not displayed. Here is an output from wrapper.html() after button is clicked:</p>
<pre><code>&lt;div&gt;&lt;button type=&quot;button&quot; class=&quot;v-btn v-btn--elevated v-theme--light v-btn--density-default v-btn--size-default v-btn--variant-elevated open-dialog-btn&quot;&gt;&lt;span class=&quot;v-btn__overlay&quot;&gt;&lt;/span&gt;&lt;span class=&quot;v-btn__underlay&quot;&gt;&lt;/span&gt;
    &lt;!----&gt;&lt;span class=&quot;v-btn__content&quot; data-no-activator=&quot;&quot;&gt;click me please&lt;/span&gt;
    &lt;!----&gt;
    &lt;!----&gt;
  &lt;/button&gt;
  &lt;!----&gt;
  &lt;!--teleport start--&gt;
  &lt;!--teleport end--&gt;
&lt;/div&gt;

AssertionError: expected false to be truthy
    at ....../HelloDialog.spec.js:27:56
</code></pre>
<p>here is test section from <strong>vite.config.js</strong>:</p>
<pre><code>  test: {
    // https://vitest.dev/config/
    globals:true,
    environment: 'happy-dom',
    setupFiles: &quot;vuetify.config.js&quot;,
    deps: {
      inline: [&quot;vuetify&quot;],
    },
  },
</code></pre>
<p>and here is <strong>vuetify.config.js</strong>:</p>
<pre><code>global.CSS = { supports: () =&gt; false };
</code></pre>
<p>here some versions from <strong>package.json</strong>:</p>
<pre><code>  &quot;dependencies&quot;: {
    &quot;@mdi/font&quot;: &quot;7.1.96&quot;,
    &quot;@pinia/testing&quot;: &quot;^0.0.14&quot;,
    &quot;axios&quot;: &quot;^1.2.0&quot;,
    &quot;dotenv&quot;: &quot;^16.0.3&quot;,
    &quot;happy-dom&quot;: &quot;^8.1.1&quot;,
    &quot;jsdom&quot;: &quot;^20.0.3&quot;,
    &quot;lodash&quot;: &quot;^4.17.21&quot;,
    &quot;pinia&quot;: &quot;^2.0.27&quot;,
    &quot;roboto-fontface&quot;: &quot;*&quot;,
    &quot;vue&quot;: &quot;^3.2.45&quot;,
    &quot;vuetify&quot;: &quot;3.0.6&quot;,
    &quot;webfontloader&quot;: &quot;^1.0.0&quot;
  },
  &quot;devDependencies&quot;: {
    &quot;@vitejs/plugin-vue&quot;: &quot;^4.0.0&quot;,
    &quot;@vue/test-utils&quot;: &quot;^2.2.6&quot;,
    &quot;vite&quot;: &quot;^4.0.3&quot;,
    &quot;vite-plugin-vuetify&quot;: &quot;^1.0.0-alpha.12&quot;,
    &quot;vitest&quot;: &quot;^0.26.2&quot;
  }
</code></pre>
<p>I have tried everything at this point, and I think the problem has something to do with v-dialog using teleport component. After struggling for several days trying to figure out I settled on using a stub to not use a real dialog when testing but I really don't like this approach.</p>
<p>any ideas would be greatly appreciated</p>

Answers:
import { mount } from '@vue/test-utils';
import { createVuetify } from 'vuetify';
import HelloDialog from '@/components/HelloDialog.vue';
import '@vuetify/styles';

describe('HelloDialog', () => {
  let wrapper;
  let vuetify;

  beforeEach(() => {
    vuetify = createVuetify();
  });

  describe('dialog tests', () => {
    beforeEach(() => {
      wrapper = mount(HelloDialog, {
        global: {
          plugins: [vuetify],
        },
        shallow: true,
      });
    });

    test('test dialog', async () => {
      expect(wrapper.find('.dialog-content').exists()).toBeFalsy();
      await wrapper.find('.open-dialog-btn').trigger('click');
      expect(wrapper.find('.dialog-content').exists()).toBeTruthy();
    });
  });
});

