Title: How to Mock Pulumi Resources in Go Unit Tests?.
Body: <p>I have a function that takes an input of an AWS OpenIdConnectProvider Pulumi Resource and creates a IAM Role with an AssumeRolePolicy attached that contains info from that OIDC provider.</p>
<p><strong>The Problem:</strong> I am trying to write a test for this function and mock out a OIDC provider to feed in as input for the function call. I'm having trouble understanding how to properly mock this so that the test output shows what I expect, currently it appears that the mocked data isn't coming up like I'd expect.</p>
<p>It seems like I'm not using the mock correctly, but I went off the <a href="https://github.com/pulumi/examples/blob/master/testing-unit-go/main_test.go" rel="nofollow noreferrer">example here</a></p>
<p><a href="https://www.pulumi.com/docs/guides/testing/unit/" rel="nofollow noreferrer">Further Docs here</a></p>
<pre class="lang-golang prettyprint-override"><code>package myPkg

import (
   &quot;github.com/pulumi/pulumi-aws/sdk/v5/go/aws/iam&quot;
   &quot;github.com/pulumi/pulumi/sdk/v3/go/pulumi&quot;
)

func CreateMyCustomRole(ctx *pulumi.Context, name string, oidcProvider *iam.OpenIdConnectProvider, opts ...pulumi.ResourceOption) (*iam.Role, error) {
    role := &amp;iam.Role{}

    componentURN := fmt.Sprintf(&quot;%s-custom-role&quot;, name)

    err := ctx.RegisterComponentResource(&quot;pkg:aws:MyCustomRole&quot;, componentURN, role, opts...)
    if err != nil {
        return nil, err
    }

    url := oidc.Url.ApplyT(func(s string) string {
        return fmt.Sprint(strings.ReplaceAll(s, &quot;https://&quot;, &quot;&quot;), &quot;:sub&quot;)
    }).(pulumi.StringOutput)

    assumeRolePolicy := pulumi.Sprintf(`{
            &quot;Version&quot;: &quot;2012-10-17&quot;,
            &quot;Statement&quot;: [{
                &quot;Effect&quot;: &quot;Allow&quot;,
                &quot;Principal&quot;: { &quot;Federated&quot;: &quot;%s&quot; },
                &quot;Action&quot;: &quot;sts:AssumeRoleWithWebIdentity&quot;,
                &quot;Condition&quot;: {
                    &quot;StringEquals&quot;: {
                        &quot;%s&quot;: [
                            &quot;system:serviceaccount:kube-system:*&quot;,
                            &quot;system:serviceaccount:kube-system:cluster-autoscaler&quot;
                        ]
                    }
                }
            }]
        }`, oidcProvider.Arn, url)

    roleURN := fmt.Sprintf(&quot;%s-custom-role&quot;, name)

    role, err = iam.NewRole(ctx, roleURN, &amp;iam.RoleArgs{
            Name:             pulumi.String(roleURN),
            Description:      pulumi.String(&quot;Create Custom Role&quot;),
            AssumeRolePolicy: assumeRolePolicy,
            Tags:             pulumi.ToStringMap(map[string]string{&quot;project&quot;: &quot;test&quot;}),
        })
    if err != nil {
        return nil, err
    }

    return role, nil
}

</code></pre>
<pre class="lang-golang prettyprint-override"><code>package myPkg

import (
    &quot;sync&quot;
    &quot;testing&quot;

    &quot;github.com/pulumi/pulumi-aws/sdk/v5/go/aws/iam&quot;
    &quot;github.com/pulumi/pulumi/sdk/v3/go/common/resource&quot;
    &quot;github.com/pulumi/pulumi/sdk/v3/go/pulumi&quot;
    &quot;github.com/stretchr/testify/assert&quot;
)

type mocks int

func (mocks) NewResource(args pulumi.MockResourceArgs) (string, resource.PropertyMap, error) {
    return args.Name + &quot;_id&quot;, args.Inputs, nil
}

func (mocks) Call(args pulumi.MockCallArgs) (resource.PropertyMap, error) {
    outputs := map[string]interface{}{}
    if args.Token == &quot;aws:iam/getOpenidConnectProvider:getOpenidConnectProvider&quot; {
        outputs[&quot;arn&quot;] = &quot;arn:aws:iam::123:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/abc&quot;
        outputs[&quot;id&quot;] = &quot;abc&quot;
        outputs[&quot;url&quot;] = &quot;https://someurl&quot;
    }
    return resource.NewPropertyMapFromMap(outputs), nil
}

func TestCreateMyCustomRole(t *testing.T) {
    err := pulumi.RunErr(func(ctx *pulumi.Context) error {

        // Gets the mocked OIDC provider to use as input for the CreateDefaultAutoscalerRole
        oidc, err := iam.GetOpenIdConnectProvider(ctx, &quot;get-test-oidc-provider&quot;, pulumi.ID(&quot;abc&quot;), &amp;iam.OpenIdConnectProviderState{})
        assert.NoError(t, err)

        infra, err := CreateMyCustomRole(ctx, &quot;role1&quot;, oidc})
        assert.NoError(t, err)

        var wg sync.WaitGroup
        wg.Add(1)

        // check 1: Assume Role Policy is formatted correctly
        pulumi.All(infra.URN(), infra.AssumeRolePolicy).ApplyT(func(all []interface{}) error {
            urn := all[0].(pulumi.URN)
            assumeRolePolicy := all[1].(string)

            assert.Equal(t, `{
            &quot;Version&quot;: &quot;2012-10-17&quot;,
            &quot;Statement&quot;: [{
                &quot;Effect&quot;: &quot;Allow&quot;,
                &quot;Principal&quot;: { &quot;Federated&quot;: &quot;arn:aws:iam::123:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/abc&quot; },
                &quot;Action&quot;: &quot;sts:AssumeRoleWithWebIdentity&quot;,
                &quot;Condition&quot;: {
                    &quot;StringEquals&quot;: {
                        &quot;someurl:sub&quot;: [
                            &quot;system:serviceaccount:kube-system:*&quot;,
                            &quot;system:serviceaccount:kube-system:cluster-autoscaler&quot;
                        ]
                    }
                }
            }]
        }`, assumeRolePolicy)

            wg.Done()
            return nil
        })

        wg.Wait()
        return nil
    }, pulumi.WithMocks(&quot;project&quot;, &quot;stack&quot;, mocks(0)))
    assert.NoError(t, err)
}

Output
</code></pre>
<pre><code>                        Diff:
                        --- Expected
                        +++ Actual
                        @@ -4,3 +4,3 @@
                                        &quot;Effect&quot;: &quot;Allow&quot;,
                        -               &quot;Principal&quot;: { &quot;Federated&quot;: &quot;arn:aws:iam::123:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/abc&quot; },
                        +               &quot;Principal&quot;: { &quot;Federated&quot;: &quot;&quot; },
                                        &quot;Action&quot;: &quot;sts:AssumeRoleWithWebIdentity&quot;,
                        @@ -8,3 +8,3 @@
                                            &quot;StringEquals&quot;: {
                        -                       &quot;someurl:sub&quot;: [
                        +                       &quot;:sub&quot;: [
                                                    &quot;system:serviceaccount:kube-system:*&quot;,
        Test:           TestCreateMyCustomRole
</code></pre>
<pre><code></code></pre>

Answers:
```python
import unittest
from unittest.mock import patch, MagicMock
from pulumi import run_err

def create_my_custom_role(ctx, name, oidc_provider):
    role = None
    component_urn = f"{name}-custom-role"
    err = ctx.register_component_resource(component_urn, role, oidc_provider)
    if err:
        return None, err

    url = oidc_provider.url.apply(lambda s: s.replace("https://", "").replace(":sub", ":sub"))
    assume_role_policy = {
        "Version": "2012-10-17",
        "Statement": [
            {
                "Effect": "Allow",
                "Principal": {"Federated": ""},
                "Action": "sts:AssumeRoleWithWebIdentity",
                "Condition": {
                    "StringEquals": {
                        "someurl:sub": [
                            "system:serviceaccount:kube-system:*",
                            "system:serviceaccount:kube-system:cluster-autoscaler"
                        ]
                    }
                }
            }
        ]
    }

    role_urn = f"{name}-custom-role"
    role, err = iam.Role.create(ctx, role_urn, {
        "Name": role_urn,
        "Description": "Create Custom Role",
        "AssumeRolePolicy": assume_role_policy,
        "Tags": {"project": "test"}
    })
    if err:
        return None, err

    return role, None

class TestCreateMyCustomRole(unittest.TestCase):
    @patch('pulumi.runtime.get_resource')
    def test_create_my_custom_role(self, mock_get_resource):
        mock_resource = MagicMock()
        mock_resource.return_value = {
            'arn': 'arn:aws:iam::123:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/abc',
            'id': 'abc',
            'url': 'https://someurl'
        }
        mock_get_resource.return_value = mock_resource

        err = run_err(create_my_custom_role, 'test', 'oidc-provider', opts=['--resource-name', 'test'])
        self.assertIsNone(err)

        role, err = create_my_custom_role('test', 'oidc-provider', 'oidc-provider')
        self.assertIsNone(err)

        # Check Assume Role Policy is formatted correctly
        assume_role_policy = role.assume_role_policy.apply(lambda p: p.replace('https://', '').replace(':sub', ':sub'))
        assert assume_role_policy == {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Effect": "Allow",
                    "Principal": {"Federated": ""},
                    "Action": "sts:AssumeRoleWithWebIdentity",
                    "Condition": {
                        "StringEquals": {
                            "someurl:sub": [
                                "system:serviceaccount:kube-system:*",
                                "system:serviceaccount:kube-system:cluster-autoscaler"
                            ]
                        }
                    }
                }
            ]
        }
```

Questions:
Title: How do I pass a double value to my C mock function with cmocka will_return()?.
Body: <p>I am using <a href="https://cmocka.org" rel="nofollow noreferrer">cmocka</a> to unit test a C project.</p>
<p>I want to mock a call to another modules made in my C function under test. This function in the other module deals with doubles, not ints.  The <code>will_return</code> documentation says it passes integer values, and I can see that if I call <code>will_return(__wrap_other_func, 42.99)</code> then the value passed into <code>__wrap_other_func</code> and pulled out through <code>double value = mock_type(double)</code> will be <code>42.0</code>, not the desired <code>42.99</code>.</p>
<pre class="lang-c prettyprint-override"><code>double __wrap_other_func(double param) {
  check_expected(param);
  double value = mock_type(double); // will_return() has converted this, effectively rounding
  fprintf(stderr, &quot;%lf\n&quot;, value);
  return value;
}

static void test_this_func(void **state) {
  (void) state;
  expect_value(__wrap_other_func, param, 1.0);
  will_return(__wrap_other_func, 42.99);
  int result = this_func(12.34); // this_func() will call other_func()
  ...
  assert(result == 0); 
  /* the assert is failing because the double 42.99 is converted to an integer,
     then back to a double, rounding off all the decimal places. */
}

&gt; 42.0
</code></pre>
<p>Has anyone figured out how to pass doubles into the mock function with <code>will_return</code> or some other cmocka method?  I'm stuck on this.</p>
<p>I was expecting to be able to pass non-integer values to my mock function using cmocka.</p>
<p>When I tried that using <code>will_return()</code>, I found all double values were rounded to integer equivalents.</p>
<p>I have pored over the cmocka documentation and searched for cmocka examples online.</p>
<p><strong>Update 2023-11-19</strong>
<strong>I have a solution.</strong></p>
<p>The <code>cmocka</code> main repo at <a href="https://git.cryptomilk.org/projects/cmocka.git" rel="nofollow noreferrer">cryptomilk</a> was updated by Andreas Schneider so that mocks work with real numbers (floats and doubles) as expected.
Thank you Andreas!</p>
<p>With the 2023-11-17 head of the main branch built and installed on my system, this code now works as expected.</p>
<pre><code>double __wrap_other_func(double param) {
  // verify that the expected value was passed in to the mock
  check_expected(param);
  // assign the return value
  double value = mock_float; 
// will_return_float() can deal with real numbers (doubles and floats)
  fprintf(stderr, &quot;%lf\n&quot;, value); // this will print the real number value now
  return value;
}

static void test_this_func(void **state) {
  (void) state;
  // make sure the argument passed to the mock is correct
  expect_value(__wrap_other_func, param, 1.0);
  // tell the mock what to return
  will_return_float(__wrap_other_func, 42.99);
  // call this_func normally. The mock for other_func will get called
  int result = this_func(12.34); // this_func() will call other_func()
  ...
  assert(result == 0); 
  // the assert is now passing because the double 42.99 remains a double
}

&gt; 42.99
</code></pre>
<p>Thanks to everyone who offered comments and answers.</p>

Title: What is the use of zero offset in fseek() function with SEEK_CUR?.
Body: <pre><code>while (fread(&amp;product, sizeof(Product), 1, file) == 1) {
        product.price *= 2.0;
        fseek(file, -sizeof(Product), SEEK_CUR);
        fwrite(&amp;product, sizeof(Product), 1, file);
        fseek(file, 0, SEEK_CUR);
}
</code></pre>
<p>Using the code above, I tried to double the price of each product in the binary file, where each record is an instance of a Product struct. When I ran this code, it updated all the prices in the file correctly.</p>
<p>As far as I know, <code>fread</code> automatically moves the file pointer to the next record. Using the first <code>fseek</code>, the code moves the file pointer back to the beginning of the record. Then it updates it using <code>fwrite</code>. <code>fwrite</code> automatically moves the file pointer to the next record. In the while loop, <code>fread</code> should continue to read the next record, and so on.</p>
<p>It seems that <code>fseek(file, 0, SEEK_CUR);</code> is unnecessary here. However, if I remove it, the code enters an infinite loop. I cannot figure out why this happens.</p>
<p>I tried to observe the value of file pointer using <code>ftell</code>. But I did not see any change its value after <code>fseek(file, 0, SEEK_CUR);</code>.</p>

Title: How to programatically force Windows to update a file&#39;s reported on-disk size, while the file is being written?.
Body: <p>I've got a program that opens an ASCII log file and writes lines of text to the end of it whenever events occur.  The timing of the events is unpredictable; they may happen many times per second, or they may only happen once every few hours.</p>
<p>This all works fine; the problem comes when I want to see what the current size of the log file is, while the program is running.  Under Windows, if I enter <code>dir</code> into a DOS shell, the log file's size shows up as 0 bytes, until such time as my program closes the log file.  (Interestingly, if I do a <code>dir my_file_name.log</code>, the file's size updates, but just a plain <code>dir</code> does not update the file size)</p>
<p>This is less useful than I would like; however according to <a href="https://superuser.com/questions/727883/why-some-write-in-progress-files-report-0-byte-but-shrinking-drives-free-space">this  question/answer on SuperUser.com</a>, that behavior is a &quot;feature&quot; of the Windows OS.  The answer even gives a hack work-around to force the file-size figure to update (by entering <code>type my_file_name.log &gt; nul</code> into the DOS box).</p>
<p>My question is, is there some programmatic way to force that same update from within my program?  I'd like to be able to at least occasionally force the correct size to be shown, without having to tell the user to manually perform a work-around step.</p>
<p>I tried simulating the behavior of <code>type</code> from within my program, by doing a separate call to <code>fopen()</code> and <code>fclose()</code> on my log file's filepath, but it didn't seem to have any effect.</p>
<p>I also tried forcing the issue by calling <code>fclose()</code> on my log file's file-handle, and then re-opening the file in append-mode immediately afterwards (via <code>fopen()</code> again), but for some reason the <code>fopen()</code> call failed.  (I don't really want to do this anyway, for precisely the reason that re-opening the file might fail, leaving my program in an undesirable state)</p>
<p>See toy example program below:</p>
<pre><code>#include &lt;stdio.h&gt;

int main(int args, char ** argv)
{
   FILE * fpOut = fopen(&quot;my_log_file.txt&quot;, &quot;w&quot;);
   if (fpOut)
   {
      for (int i=0; i&lt;1000; i++)
      {
         fprintf(fpOut, &quot;Event %i occurred\n&quot;, i);
         fflush(fpOut);

         Sleep(1000);

         // is there something I could call here to make the file's new size visible to the world?
      }
      fclose(fpOut);
   }
   return 0;
}
</code></pre>

Title: c++ read data from file and convert to template type of class.
Body: <p>Following case:</p>
<pre><code>template &lt;typename NumberType = double&gt;
class A
{
   //constructur, destructor,...

   //member variable
   std::vector&lt;std::vector&lt;NumberType&gt; matrix_;

   //member function
   void read(std::ifstream fileIn)
   {
       std::string line, word;
       unsigned int row = 0;
       while (std::getline(fileIn, line))
       {
         std::istringstream lineStream(line);
         unsigned int col = 0;
         while (std::getline(lineStream, word, ','))
            {
               matrix_[row][col] = std::stod(word); // how to convert to NumberType?
               col++;
            }
         row++;
      }
   }
};
</code></pre>
<p>I read matrix-like data from a csv file and want to store the entries in a container, whose type is a template type from a class. At the moment, I instantiate the class only for <code>NumberType = double</code> , so I hard-coded <code>std::stod(word)</code> for testing.</p>
<p>But how can I convert the string <code>word</code> to <code>NumberType</code>? NumberType can be float, double, long double,..., but not string, unsigned int, int,...</p>

Answers:
```cpp
template <typename NumberType>
class A
{
   //constructur, destructor,...

   //member variable
   std::vector<std::vector<NumberType>> matrix_;

   //member function
   void read(std::ifstream fileIn)
   {
       std::string line, word;
       unsigned int row = 0;
       while (std::getline(fileIn, line))
       {
         std::istringstream lineStream(line);
         unsigned int col = 0;
         while (std::getline(lineStream, word, ','))
         {
             matrix_[row][col] = static_cast<NumberType>(std::stof(word)); // convert to float first then to NumberType
             col++;
         }
         row++;
      }
   }
};
```

```javascript
{
  "scripts": {
    "build": {
      "test": "vite",
      "dev": "vite",
      "build:foo": "cp -r foo/dist node_modules/foo",
      "postbuild": "cp -r foo/dist node_modules/foo"
    }
  },
  "vite": {
    "build": {
      "postbuild": "cp -r foo/dist node_modules/foo"
    }
  }
}
```

Explanation: The issue arises because Vite doesn't create the necessary symlinks for file-based dependencies by default. The provided `package.json` configuration script, specifically the `postbuild` script, ensures that the `node_modules/foo` directory is populated with the correct contents from the `foo` directory after building the project. This resolves the import issues and allows the project to function as expected.

