class WarehouseSum:
    def __init__(self):
        self.wh_units = {}

    def available_units(self, warehouse: str) -> int:
        if warehouse not in self.wh_units:
            sql = "SELECT sum(units) as tot_units FROM warehouse WHERE warehouse = '{}'".format(warehouse)
            # assuming a database connection is established outside of this function
            # and a cursor object is available to execute SQL queries
            cursor = # establish database connection and get cursor
            cursor.execute(sql)
            row = cursor.fetchone()
            self.wh_units[warehouse] = row[0]
        return self.wh_units.get(warehouse, 0)


# Example usage:
