def least_change(original, reordered):
    extracts = []
    for item in original:
        if original.index(item) != reordered.index(item):
            extracts.append(item)
    return sorted(extracts)

original = ["life", "is", "trying", "things", "to", "see", "if", "they", "work"]
reordered = ["life", "they", "is", "trying", "to", "things", "work", "see", "if"]

print(least_change(original, reordered))
