from collections import deque

def maxProfit(k, prices):
    n = len(prices)
    if k >= n // 2:
        return sum(max(0, b - a) for a, b in zip(prices, prices[1:]))

    dp = [0] * (2 * k + 1)
    dq = [0] * (2 * k + 1)
    queue = deque()

    for price in prices:
        for i in range(2 * k, -1, -1):
            if i >= k:
                dp[i] = max(dp[i], dq[i - k] + price)
            if i > 0:
                dp[i] = max(dp[i], dp[i - 1] - price)
        queue.append(dp)
        dp, dq = dq, dp

    return max(dp)

