Title: Next Auth google OAuth with custom backend&#39;s access token and refresh token.
Body: <p>I have a NestJS backend that exposes the following API:</p>
<pre><code>   @Post('sign-in-with-google-account')
   async signInWithGoogleAccount(
     @Body body: { idToken: string }, 
     @Res({ passthrough: true }) response: Response
   ) {
     const user = await getUserFromGoogleIdToken(body.idToken)
     const tokens = await generateAccessAndRefreshTokensForUser(user)

     response.cookie('refreshToken', tokens.refreshToken, {
         httpOnly: true,
         expires: new Date(tokenExpirationDate),
         secure: true,
         sameSite: 'none'
     })

     return { accessToken: tokens.accessToken }
   }
</code></pre>
<p>It receives id token from google oauth, finds the user in the DB and signs a JWT access token and refresh token. The refresh token is stored as <code>httpOnly</code> cookie and the access token is returned.</p>
<p>Now in my next.js app configured with <code>next-auth</code> I have the following:</p>
<pre><code>import GoogleProvider from &quot;next-auth/providers/google&quot;;

...
providers: [
  GoogleProvider({
    clientId: process.env.GOOGLE_CLIENT_ID,
    clientSecret: process.env.GOOGLE_CLIENT_SECRET
  })
]
...

</code></pre>
<p>The problem is that <code>next-auth</code> generates its own tokens. But I want <code>next-auth</code> to use my own access and refresh tokens from the NestJS backend, how can I do that?</p>
<p>Also, In NestJS I have a API to refresh the access token like so:</p>
<pre><code>@Get('refresh-access-token')
async refreshAccessToken(@Req() request: Request) {
  const accessToken = await getNewAccessTokenFromRefreshToken(request.cookies.refreshToken)
  return { accessToken } 
}
</code></pre>
<p>How can I tell <code>next-auth</code> to refresh the access token using <code>refresh-access-token</code> API every 10 minutes (the access token expiration date)?</p>

Answers:
```javascript
// In your next-auth options
import { NextAuthOptions } from 'next-auth';

const options: NextAuthOptions = {
  // Your Google OAuth provider options
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
      // Use your custom access and refresh tokens
      callbacks: {
        async token(user, account, profile) {
          return {
            ...user,
            accessToken: process.env.ACCESS_TOKEN,
            refreshToken: process.env.REFRESH_TOKEN,
          };
        },
        async session(session, token) {
          session.accessToken = token.accessToken;
          session.refreshToken = token.refreshToken;
          return session;
        },
      },
    }),
  ],
  // Configure JWT tokens to be used for sessions
  jwt: {
    secret: process.env.JWT_SECRET,
    encodingType: 'HS256',
  },
  // Configure the refresh token to be used for sessions
  refreshTokens: {
    class: 'Postgres',
    // Store refresh tokens in the database
    async store(token, user) {
      const refreshToken = token.refreshToken;
      // Store the refresh token in your database
      await storeRefreshToken(user, refreshToken);
      return token;
    },
  },
};

// In your next-auth options to refresh the access token every 10 minutes
import { NextAuthRequest, NextAuthResponse } from 'next-auth';

const refreshAccessToken = async (req: NextAuthRequest, res: NextAuthResponse) => {
  const now = Date.now();
  const accessTokenExpirationDate = process.env.ACCESS_TOKEN_EXPIRATION_DATE;
  const refreshToken = req.cookies.refreshToken;

  if (!refreshToken) {
    return res.status(401).json({ error: 'No refresh token provided' });
  }

  const accessTokens = await getAccessTokensForRefreshToken(refreshToken);

  if (!accessTokens || accessTokens.length === 0) {
    return res.status(401).json({ error: 'Invalid refresh token' });
  }

  const accessToken = accessTokens[0];
  const refreshToken = accessTokens[1];

  const tokenExpirationDate = new Date(accessTokenExpirationDate);
  const nowDate = new Date(now);

  if (tokenExpirationDate < nowDate) {
    return res.status(401).json({ error: 'Access token has expired' });
  }

  const newAccessToken = await getNewAccessTokenFromRefreshToken(refreshToken);
  const newAccessTokenExpirationDate = new Date(newAccessToken.tokenExpirationDate);

  if (newAccessTokenExpirationDate < nowDate) {
    return res.status(401).json({ error: 'Access token has expired' });
  }

  // Update the access token in the database
  await updateAccessToken(accessToken, newAccessToken);

  return { accessToken: newAccessToken.accessToken };
};

// Call the refreshAccessToken function every 10 minutes
setInterval(() => {
  // Get the current request
  const req = reqs.nextAuth as NextAuthRequest;
  // Get the current response
  const res = ress.nextAuth as NextAuthResponse;

  // Refresh the access token
  refreshAccessToken(req, res);
}, 10 * 60 * 1000);
```

