```csharp
using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class CustomHttpClient : HttpClient
{
    private readonly TimeSpan _connectTimeout;
    private readonly TimeSpan _responseTimeout;

    public CustomHttpClient(TimeSpan connectTimeout, TimeSpan responseTimeout)
    {
        _connectTimeout = connectTimeout;
        _responseTimeout = responseTimeout;
    }

    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        try
        {
            var connectTimeout = TimeSpan.FromMilliseconds(_connectTimeout.TotalMilliseconds);
            var response = await SendAsync(request, cancellationToken);

            if (response.RequestAborted)
            {
                throw new TaskCanceledException();
            }

            var responseTimeout = TimeSpan.FromMilliseconds(_responseTimeout.TotalMilliseconds);
            await Task.Delay(responseTimeout - response.Content.Headers.ContentLength.Value, cancellationToken);

            return response;
        }
        catch (TaskCanceledException)
        {
            return null;
        }
        catch (HttpRequestException ex)
        {
            throw;
        }
    }
}

public class Program
{
    public static async Task Main()
    {
        var client = new CustomHttpClient(TimeSpan.FromSeconds(5), TimeSpan.FromSeconds(10));

        var response = await client.GetAsync("https://example.com");

        if (response == null)
        {
            Console.WriteLine("Request cancelled");
        }
        else
        {
            Console.WriteLine("Request completed successfully");
        }
    }
}
```

