import requests

def send_location_request_message(phone_number, api_key, api_secret):
    payload = {
        "recipient_type": "individual",
        "to": phone_number,
        "type": "interactive",
        "interactive": {
            "type": "location_request_message",
            "body": {
                "type": "text",
                "text": ""
            },
            "action": {
                "name": "send_location"
            }
        }
    }

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }

    response = requests.post("https://graph.facebook.com/v13.0/ messaging", json=payload, headers=headers)

    if response.status_code == 200:
        print("Location request message sent successfully.")
    else:
        print("Failed to send location request message.")

# Example usage:
phone_number = "+1234567890"
api_key = "YOUR_API_KEY"
api_secret = "YOUR_API_SECRET"

send_location_request_message(phone_number, api_key, api_secret)
```

Note: Replace `YOUR_API_KEY` and `YOUR_API_SECRET` with your actual Facebook Messenger API key and secret. Also, ensure that you have the necessary permissions to send location request messages.

