Title: C sockets on windows, randomly getting recv errors but errno is at 0?.
Body: <p>I have a client and a server using sockets on windows. I start the server before the client, wait for it to hang and then start the client. Doing so, the call to <code>recv()</code> will randomly (half of the time) return -1 and when I print errno it is at 0 (No Error)... The other half of the time it will receive the message and print it normally then close... Is there something wrong with this code ?</p>
<p><strong>client.c</strong></p>
<pre><code>#include &lt;winsock2.h&gt;
#include &lt;Ws2tcpip.h&gt;
#include &lt;stdio.h&gt;
#include &lt;errno.h&gt;

#define BUFFER_LEN 200

int main()
{
    WSADATA WSAData;
    WSAStartup(MAKEWORD(2,0), &amp;WSAData);

    SOCKET sock;
    SOCKADDR_IN address;
    // address.sin_addr.s_addr = inet_addr(&quot;127.0.0.1&quot;);
    InetPton(AF_INET, &quot;127.0.0.1&quot;, &amp;address.sin_addr.s_addr);
    address.sin_family = AF_INET;
    address.sin_port = htons(8888);

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        printf(&quot;Erreur lors de la création du socket. %s\n&quot;, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if ((connect(sock, (SOCKADDR *)&amp;address, sizeof(address))) == -1) {
        sprintf(&quot;Erreur lors de la connexion au socket. %s\n&quot;, strerror(errno));
        exit(EXIT_FAILURE);
    }

    char *msg = &quot;Coucou\n&quot;;
    printf(&quot;Envoi de coucou\n&quot;);
    int bytesSent;

    if ((bytesSent = send(sock, msg, strlen(msg), 0)) == -1) {
        sprintf(&quot;Erreur lors l'envoi du message. %s\n&quot;, strerror(errno));
        exit(EXIT_FAILURE);
    }

    printf(&quot;Bytes envoyés : %d\n&quot;, bytesSent);

    WSACleanup();

    return 0;
}
</code></pre>
<p><strong>server.c</strong></p>
<pre><code>#include &lt;winsock2.h&gt;
#include &lt;Ws2tcpip.h&gt;
#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;errno.h&gt;

#define BACKLOG 3 // taille de la file d'attente
#define BUFFER_LEN 200 // taille du buffer de lecture

int main()
{
    WSADATA WSAData;
    WSAStartup(MAKEWORD(2,0), &amp;WSAData);

    SOCKET sockfd;
    SOCKADDR_IN address;
    // address.sin_addr.s_addr = inet_addr(&quot;127.0.0.1&quot;);
    address.sin_addr.s_addr = htonl(INADDR_ANY);  
    address.sin_family = AF_INET;
    address.sin_port = htons(8888); // host to network short (conversion de host byte order en network byte order)

    printf(&quot;Démarrage du serveur\n&quot;);

    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        printf(&quot;Erreur lors de la création du socket. %s\n&quot;, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if ((bind(sockfd, (SOCKADDR *)&amp;address, sizeof(address))) == -1) {
        printf(&quot;Erreur lors de l'ouverture du socket. %s\n&quot;, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if ((listen(sockfd, BACKLOG)) == -1) {
        printf(&quot;Erreur lors de l'écoute du socket. %s\n&quot;, strerror(errno));
        exit(EXIT_FAILURE);
    }

    SOCKET clientSocket;
    SOCKADDR_IN clientAddress;
    int addrLen = sizeof(clientAddress);
    if ((clientSocket = accept(sockfd, (struct sockaddr *) &amp;clientAddress, &amp;addrLen)) == -1) {
        printf(&quot;Erreur lors de l'acceptation de la connexion. %s\n&quot;, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Convertion de l'IP en texte
    char ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &amp;(clientAddress.sin_addr), ip, INET_ADDRSTRLEN);
    printf(&quot;Connexion de %s:%i\n&quot;, ip, clientAddress.sin_port);

    char buffer[BUFFER_LEN];
    int len = recv(clientSocket, buffer, BUFFER_LEN, 0);

    if (len == -1 &amp;&amp; errno != EAGAIN) {
        printf(&quot;Erreur lors de la réception du message. %s (%d)\n&quot;, strerror(errno), errno);
        exit(EXIT_FAILURE);
    } else if (len == 0) {
        printf(&quot;Le client s'est déconnecté (extrémité de la socket fermée)\n&quot;);
        exit(EXIT_FAILURE);
    } else if (len &gt; 0) {
        printf(&quot;Message reçu : %s\n&quot;, buffer);
    }

    closesocket(clientSocket);
    closesocket(sockfd);

    WSACleanup();

    return 0;
}
</code></pre>
<p>I also should mention that I compile with <code>gcc main.c -lws2_32 -g -Wall</code></p>

Title: In network programming, must the accepting end close both sockets?.
Body: <p>I raised a question earlier, and one of the answers involved another question.</p>
<p>That is to say, in general, the accepting end should create two sockets to establish the accepting end. like this:</p>
<h3>Python</h3>
<pre class="lang-py prettyprint-override"><code>from socket import *
sockfd = socket(...)
# ...
client_sockfd, addr = sockfd.accept()
# ...
client_sockfd.close()
sockfd.close()
</code></pre>
<h3>C</h3>
<pre class="lang-c prettyprint-override"><code>int sockfd, client_sockfd;
sockfd = socket(...);
// ...
client_sockfd = accept(sockfd, ...);
// ...
shutdown(client_sockfd, 2);
shutdown(sockfd, 2);
close(client_sockfd);
close(sockfd);
</code></pre>
<hr>
<p>So can we skip the task of creating the <code>client_sockfd</code> variable? like this:</p>
<h3>Python</h3>
<pre class="lang-py prettyprint-override"><code>sockfd = socket(...)
# ...
sockfd, addr = sockfd.accept()
# ...
sockfd.close()
</code></pre>
<h3>C</h3>
<pre class="lang-c prettyprint-override"><code>int sockfd;
struct sockaddr_in server, client;
socklen_t client_size = sizeof(client);
sockfd = socket(...);
// ...
sockfd = accept(sockfd, (struct sockaddr *)&amp;client, &amp;client_size);
</code></pre>
<p>Or it could be like this:</p>
<h3>Python</h3>
<pre class="lang-py prettyprint-override"><code>sockfd = socket(...)
# ...
client_sockfd, addr = sockfd.accept()
sockfd.close()
# ...
client_sockfd.close()
</code></pre>
<h3>C</h3>
<pre class="lang-c prettyprint-override"><code>int sockfd = socket(...);
int client_sockfd;
// ...
client_sockfd = accept(sockfd, ...);
shutdown(sockfd, 2);
close(sockfd);
// ...
shutdown(client_sockfd, 2);
close(client_sockfd);
</code></pre>
<p>As shown in the above code, can we use only one socket to complete the accepting end of the entire network programming? Is there any problem with this? (At least I didn't have any problems writing the program like this myself)</p>

Title: Get IP address (as string) from struct addrinfo.
Body: <p>I have a <code>struct addrinfo</code> and this is passed to make a connection:</p>
<pre><code>struct addrinfo* address;
...
int fd = socket(address-&gt;ai_family, address-&gt;ai_socktype, address-&gt;ai_protocol);
...
int res = ::connect(fd, address-&gt;ai_addr, address-&gt;ai_addrlen);
</code></pre>
