Answers:
```python
import requests

def ws_security(username, password, ws_url):
    try:
        headers = {
            'Authorization': f'Basic {username}:{password}',
            'Content-Type': 'text/xml; charset=utf-8'
        }

        response = requests.post(ws_url, headers=headers, verify=True)

        if response.status_code == 200:
            print("WS Connected successfully")
        else:
            print(f"WS Connection Failed with Status Code {response.status_code}")
    except Exception as e:
        print(f"WS Connection Failed with Error {str(e)}")

ws_url = "https://*************/DocumentUploadWS.wsdl"
username = "*******"
password = "*********"

ws_security(username, password, ws_url)
```

