import axios

# Assuming EXPO_PUBLIC_GOOGLE_PLACES_API_KEY is an environment variable
EXPO_PUBLIC_GOOGLE_PLACES_API_KEY = 'YOUR_API_KEY_HERE'

def get_place_photo(photo_reference: str) -> dict:
