from flask import Flask, request, jsonify
from flask_httpauth import HTTPBasicAuth
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
auth = HTTPBasicAuth()

# In-memory storage for demonstration purposes
users = {
    'admin': generate_password_hash('password')
}

# Public endpoint
@app.route('/public/a', methods=['GET'])
def public_a():
    return 'Hello from public endpoint'

# Private endpoint with authentication
@app.route('/private/b/', methods=['GET'])
@auth.login_required
def private_b():
    return 'Hello from private endpoint'

# Authentication decorator to verify credentials
@auth.verify_password
def verify_password(username, password):
    if username in users:
        return check_password_hash(users.get(username), password)
    return False

# Route to trigger a function securely
@app.route('/private/c/', methods=['POST'])
@auth.login_required
def trigger_function():
    # Trigger the function here
    return jsonify({'message': 'Function triggered successfully'})

if __name__ == '__main__':
    app.run(debug=True)
