export const sendEmail = ({ service_id, templete_id, values, theme, setIsloading, pubkey }) =&gt; {
  emailjs.send(service_id, templete_id, values, pubkey).then(
    () =&gt; {
        toast.success(&quot;Application submitted !&quot;, {theme})
        setIsloading(false);
    },
    (error) =&gt; {
      console.error(error);
      toast.error(&quot;Something went wrong.&quot;, {theme});
      setIsloading(false);

    }
  );
};
</code></pre>
<pre><code>const resolveWithSomeData = new Promise(resolve =&gt; setTimeout(() =&gt; resolve(&quot;world&quot;), 3000));
toast.promise(
    resolveWithSomeData,
    {
      pending: {
        render(){
          return &quot;I'm loading&quot;
        },
        icon: false,
      },
      success: {
        render({data}){
          return `Hello ${data}`
        },
        // other options
        icon: &quot;🟢&quot;,
      },
      error: {
        render({data}){
          // When the promise reject, data will contains the error
          return &lt;MyErrorComponent message={data.message} /&gt;
        }
      }
    }
)
</code></pre>
<p>i found this but it couldnt resolving my issue I want a custom loader on pending status</p>

Answers:
```python
# No Python code is required to solve this problem, it's a JavaScript issue.

# However, here's a modified version of your existing code that uses the promise version of React Toastify with a custom loader for the pending status.

import emailjs from "@emailjs/browser";
import { toast } from 'react-toastify';

export const sendEmail = ({ service_id, templete_id, values, theme, setIsloading, pubkey }) => {
  emailjs.send(service_id, templete_id, values, pubkey).then(
    () => {
      toast.success("Application submitted !", { theme });
      setIsloading(false);
    },
    (error) => {
      console.error(error);
      toast.error("Something went wrong.", { theme });
      setIsloading(false);
    }
  );
};

const customLoader = {
  render: ({ pending }) => {
    if (pending) {
      return <div>Loading...</div>;
    }
    return null;
  },
};

toast.configure({
  // Use the custom loader for the pending status
  toastOptions: {
    pending: {
      render: customLoader.render,
    },
    success: {
      render({ data }) {
        return `Hello ${data}`;
      },
      // other options
      icon: "🟢",
    },
    error: {
      render({ data }) {
        // When the promise reject, data will contains the error
        return <MyErrorComponent message={data.message} />;
      }
    }
  }
});

// Now you can use the promise version of React Toastify
toast.promise(
  new Promise((resolve) => setTimeout(() => resolve("world"), 3000)),
  {
    // other options
    icon: false,
  }
);
```

# Individual Tracking Pixels with Dynamic Tracking Links

We will use a combination of JavaScript and server-side programming to achieve this. Here's an example code snippet:

### Tracking Pixel Code

```html
<img src="https://example.com/tracking-pixel.php?email={{recipient_email}}&open={{open_status}}&click={{click_status}}" alt="Tracking Pixel">
```

In the above code, `{{recipient_email}}`, `{{open_status}}`, and `{{click_status}}` are placeholders for the recipient's email address, open status, and click status respectively.

### Server-side Script (PHP)

```php
<?php
// Assuming we have an array of recipients
$recipients = array('p1@example.com', 'p2@example.com', 'p3@example.com');

// Assuming we have a function to send emails
function send_email($recipient, $subject, $body) {
    // Implement email sending logic here
}

// Loop through each recipient
foreach ($recipients as $recipient) {
    // Generate a unique tracking link for each recipient
    $tracking_link = 'https://example.com/tracking-pixel.php?email=' . $recipient . '&open=0&click=0';

    // Send an email to the recipient with the tracking link
    send_email($recipient, 'Test Email', '<p>Hello ' . $recipient . ', <br> Click the link below to track the email.</p> <img src="' . $tracking_link . '">');
}
```

### JavaScript Code

```javascript
// Add event listener to the tracking pixel
document.addEventListener('DOMContentLoaded', function() {
    var trackingPixels = document.querySelectorAll('img[src*="tracking-pixel.php"]');

    trackingPixels.forEach(function(trackingPixel) {
        trackingPixel.addEventListener('load', function() {
            // Get the tracking link from the image src
            var trackingLink = trackingPixel.src;

            // Extract the email address from the tracking link
            var email = trackingLink.match(/email=([^&]*)/)[1];

            // Update the tracking status on the server-side
            fetch(trackingLink, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email: email, open: true, click: false })
            });
        });
    });
});
```

In the JavaScript code, we first add an event listener to the tracking pixel image. When the image loads, we extract the tracking link from the image src and update the tracking status on the server-side by sending a POST request with the email address, open status, and click status.

