```php
<?php

// Define the mail settings
$mailSettings = [
    'transport' => 'ses',
    'host' => 'smtp.amazonaws.com',
    'port' => 443,
    'encryption' => 'tls',
    'tls_version' => 'tls1_2',
    'username' => 'your-aws-username',
    'password' => 'your-aws-password',
];

// Create a new Swift Transport instance
$transport = Swift_SmtpTransport::newInstance(
    $mailSettings['host'],
    $mailSettings['port'],
    $mailSettings['encryption'],
    $mailSettings['tls_version']
);

// Create a new Swift Mailer instance
$mailer = Swift_Mailer::newInstance($transport);

// Define the message
$message = (new Swift_Message())
    ->setFrom('your-email@example.com')
    ->setTo('recipient-email@example.com')
    ->setBody('Hello, World!');

try {
    // Send the message
    $result = $mailer->send($message);
    if ($result === true) {
        print("Message sent successfully.");
    } else {
        print("Error sending message: " . $mailer->getLastError());
    }
} catch (Swift_TransportException $e) {
    print("Error sending message: " . $e->getMessage());
}
